75	    function escapeMarkdownText(text) {
76	        // Escape special markdown characters in regular text
77	        return text
78	            .replace(/\\/g, '\\\\')
79	            .replace(/\[/g, '\\[')
80	            .replace(/\]/g, '\\]');
81	    }
