114	    function convertListToMarkdown(list, indent = 0) {
115	        const items = [];
116	        const isOrdered = list.tagName.toLowerCase() === 'ol';
117	        const startNum = parseInt(list.getAttribute('start') || '1', 10);
118	        let itemNum = startNum;
119	        const indentStr = '  '.repeat(indent);
120	
121	        list.querySelectorAll(':scope > li').forEach(li => {
122	            const prefix = isOrdered ? `${itemNum}.` : '-';
123	            itemNum++;
124	
125	            // Process li content, handling nested lists separately
126	            const childNodes = Array.from(li.childNodes);
127	            let textContent = '';
128	            let nestedLists = '';
129	
130	            childNodes.forEach(child => {
131	                if (child.nodeType === Node.ELEMENT_NODE) {
132	                    const tagName = child.tagName.toLowerCase();
133	                    if (tagName === 'ul' || tagName === 'ol') {
134	                        // Handle nested list
135	                        nestedLists += convertListToMarkdown(child, indent + 1);
136	                    } else {
137	                        textContent += convertElementToMarkdown(child);
138	                    }
139	                } else if (child.nodeType === Node.TEXT_NODE) {
140	                    textContent += child.textContent;
141	                }
142	            });
143	
144	            const cleanText = textContent.replace(/\n/g, ' ').trim();
145	            if (cleanText) {
146	                items.push(`${indentStr}${prefix} ${cleanText}`);
147	            }
148	            if (nestedLists) {
149	                items.push(nestedLists.trimEnd());
150	            }
151	        });
152	
153	        return items.join('\n');
154	    }
