306	            // Span and other inline elements - just process children
307	            case 'span':
308	            case 'div':
309	            case 'article':
310	            case 'section':
311	            case 'main':
312	            case 'header':
313	            case 'footer':
314	            case 'aside':
315	            case 'nav':
