521	
522	    function identifySender(messageElement, index, allMessages) {
523	        // Method 1: Check for data attributes (most reliable)
524	        const authorRole = messageElement.getAttribute('data-message-author-role');
525	        if (authorRole) {
526	            return { sender: authorRole === 'user' ? 'You' : 'ChatGPT', reliable: true };
527	        }
528	
529	        // Claude: user message and assistant response have distinct markers
530	        if (messageElement.getAttribute('data-testid') === 'user-message') {
531	            return { sender: 'You', reliable: true };
532	        }
533	        if (messageElement.classList && messageElement.classList.contains('font-claude-response')) {
534	            return { sender: 'Claude', reliable: true };
535	        }
536	
537	        // Method 2: Look for avatar images with better detection
538	        const avatars = messageElement.querySelectorAll('img');
539	        for (const avatar of avatars) {
540	            const alt = avatar.alt?.toLowerCase() || '';
541	            const src = avatar.src?.toLowerCase() || '';
542	            const classes = avatar.className?.toLowerCase() || '';
543	
544	            // User indicators
545	            if (alt.includes('user') || src.includes('user') || classes.includes('user')) {
546	                return { sender: 'You', reliable: false };
547	            }
548	
549	            // Assistant indicators
550	            if (alt.includes('chatgpt') || alt.includes('assistant') || alt.includes('gpt') ||
551	                src.includes('assistant') || src.includes('chatgpt') || classes.includes('assistant')) {
552	                return { sender: 'ChatGPT', reliable: false };
553	            }
554	        }
555	
556	        // Method 3: Content analysis with better patterns
557	        const text = messageElement.textContent.toLowerCase();
558	        const textStart = text.substring(0, 200); // Look at beginning of message
559	
560	        // Strong ChatGPT indicators
561	        if (textStart.match(/^(i understand|i can help|here's|i'll|let me|i'd be happy|certainly|of course)/)) {
562	            return { sender: 'ChatGPT', reliable: false };
563	        }
564	
565	        // Strong user indicators
566	        if (textStart.match(/^(can you|please help|how do i|i need|i want|help me|could you)/)) {
567	            return { sender: 'You', reliable: false };
568	        }
569	
570	        // Method 4: Structural analysis - look at DOM structure
571	        const hasCodeBlocks = messageElement.querySelectorAll('pre, code').length > 0;
572	        const hasLongText = messageElement.textContent.length > 200;
573	        const hasLists = messageElement.querySelectorAll('ul, ol, li').length > 0;
574	
575	        // ChatGPT messages tend to be longer and more structured
576	        if (hasCodeBlocks && hasLongText && hasLists) {
577	            return { sender: 'ChatGPT', reliable: false };
578	        }
579	
580	        // Method 5: Position-based fallback with better logic
581	        // Try to detect actual alternating pattern by looking at content characteristics
582	        if (index > 0 && allMessages[index - 1]) {
583	            const prevText = allMessages[index - 1].textContent;
584	            const currentText = messageElement.textContent;
585	
586	            // If previous was short and current is long, likely user -> assistant
587	            if (prevText.length < 100 && currentText.length > 300) {
588	                return { sender: 'ChatGPT', reliable: false };
589	            }
590	
591	            // If previous was long and current is short, likely assistant -> user
592	            if (prevText.length > 300 && currentText.length < 100) {
593	                return { sender: 'You', reliable: false };
594	            }
595	        }
596	
597	        // Final fallback
598	        return { sender: index % 2 === 0 ? 'You' : 'ChatGPT', reliable: false };
599	    }
600	
601	    function extractConversationTitle() {
602	        // Try to get actual conversation title
603	        const titleSelectors = [
604	            'h1:not([class*="hidden"])',
605	            '[class*="conversation-title"]',
606	            '[data-testid*="conversation-title"]',
607	            'title'
608	        ];
609	
610	        for (const selector of titleSelectors) {
611	            const element = document.querySelector(selector);
612	            if (element && element.textContent.trim()) {
613	                let title = element.textContent.trim();
614	                // Strip platform suffixes added to document.title
615	                title = title.replace(/\s*-\s*Claude\s*$/i, '').replace(/\s*\|\s*ChatGPT\s*$/i, '').trim();
616	                // Avoid generic titles
617	                if (title && !['chatgpt', 'claude', 'new chat', 'untitled', 'chat'].includes(title.toLowerCase())) {
618	                    return title;
619	                }
620	            }
621	        }
622	
623	        return isClaudePage() ? 'Conversation with Claude' : 'Conversation with ChatGPT';
624	    }
625	
626	    // Main export logic
627	    const messages = findMessages();
628	    
629	    if (messages.length === 0) {
630	        alert('No messages found. The page structure may have changed.');
631	        return;
632	    }
633	
634	    console.log(`Processing ${messages.length} messages...`);
635	
636	    const lines = [];
637	    const title = extractConversationTitle();
638	    const date = formatDate();
639	    const url = window.location.href;
640	
641	    let sourceLabel = 'chat.openai.com';
642	    try {
643	        const host = new URL(url).hostname;
644	        if (host) sourceLabel = host;
645	    } catch (e) {}
646	    if (sourceLabel === 'chat.openai.com' && isClaudePage()) {
647	        sourceLabel = 'claude.ai';
648	    }
649	
650	    lines.push(`# ${title}\n`);
651	    lines.push(`**Date:** ${date}`);
652	    lines.push(`**Source:** [${sourceLabel}](${url})\n`);
653	    lines.push(`---\n`);
654	
655	    // Process messages with better duplicate detection
656	    const processedMessages = [];
657	    const seenContent = new Set();
658	
659	    console.log('Converting images to base64...');
660	    for (let index = 0; index < messages.length; index++) {
661	        const messageElement = messages[index];
662	        const { sender, reliable } = identifySender(messageElement, index, messages);
663	        const replyLabel = findReplyLabel(messageElement);
664	        const content = await processMessageContent(messageElement);
665	
666	        // Skip if empty or too short (reduced threshold for Chinese text)
667	        if (!content || content.trim().length < 5) {
668	            console.log(`Skipping message ${index}: too short or empty`);
669	            continue;
670	        }
671	
672	        // Create a content hash for duplicate detection
673	        const contentHash = content.substring(0, 100).replace(/\s+/g, ' ').trim();
674	        if (seenContent.has(contentHash)) {
675	            console.log(`Skipping message ${index}: duplicate content`);
676	            continue;
677	        }
678	        seenContent.add(contentHash);
679	
680	        processedMessages.push({
681	            sender,
682	            reliable,
683	            replyLabel,
684	            content,
685	            originalIndex: index
686	        });
687	
688	        console.log(`Processed message ${index + 1}/${messages.length}`);
689	    }
690	
691	    // Apply sender sequence correction only for unreliable detections
692	    for (let i = 1; i < processedMessages.length; i++) {
693	        const current = processedMessages[i];
694	        const previous = processedMessages[i - 1];
695	
696	        // Skip correction if either sender was reliably detected
697	        if (current.reliable || previous.reliable) {
698	            continue;
699	        }
700	
701	        // If we have two consecutive messages from the same sender, try to fix it
702	        if (current.sender === previous.sender) {
703	            // Use content analysis to determine which should be flipped
704	            const currentLength = current.content.length;
705	            const previousLength = previous.content.length;
706	
707	            // If current message is much longer, it's likely ChatGPT
708	            if (currentLength > previousLength * 2 && currentLength > 500) {
709	                current.sender = 'ChatGPT';
710	            } else if (previousLength > currentLength * 2 && previousLength > 500) {
711	                previous.sender = 'ChatGPT';
712	                current.sender = 'You';
713	            } else {
714	                // Default alternating fix
715	                current.sender = current.sender === 'You' ? 'ChatGPT' : 'You';
716	            }
717	
718	            console.log(`Fixed consecutive ${previous.sender} messages at positions ${i-1} and ${i}`);
719	        }
720	    }
721	
722	    // Generate final output
723	    processedMessages.forEach(({ sender, replyLabel, content }) => {
724	        const label = replyLabel ? ` (${replyLabel})` : '';
725	        lines.push(`### **${sender}**${label}\n`);
726	        lines.push(content);
727	        lines.push('\n---\n');
728	    });
729	
730	    // Create and download file
731	    const markdownContent = lines.join('\n');
732	    const blob = new Blob([markdownContent], { type: 'text/markdown' });
733	    const url2 = URL.createObjectURL(blob);
734	    const a = document.createElement('a');
735	    a.href = url2;
736	    // Use document title for better file naming (Issue #12)
737	    const safeTitle = document.title
738	        .replace(/\s*-\s*Claude\s*$/i, '')
739	        .replace(/\s*\|\s*ChatGPT\s*$/i, '')
740	        .replace(/[<>:"/\\|?*]/g, '')
741	        .replace(/\s+/g, ' ')
742	        .trim();
743	    const fallbackName = isClaudePage() ? `Claude_Conversation_${date}.md` : `ChatGPT_Conversation_${date}.md`;
744	    a.download = safeTitle ? `${safeTitle} (${date}).md` : fallbackName;
745	    document.body.appendChild(a);
746	    a.click();
747	    document.body.removeChild(a);
748	    URL.revokeObjectURL(url2);
749	
750	    console.log(`Export completed: ${processedMessages.length} messages exported`);
751	})();
